#include <stdint.h>
#include <string.h>
#include "stm32f407xx.h"

volatile uint32_t dma_done = 1;
volatile uint32_t tick = 0;

// SysTick 中斷 handler（每 1ms 觸發一次）
void SysTick_Handler(void)
{
    tick++;
}

void delay_ms(uint32_t ms)
{
    uint32_t start = tick;
    while ((tick - start) < ms);
}

void rcc_init(void) {
	RCC -> AHB1ENR |= (1 << 0);      // GPIOA
	RCC -> APB2ENR |= (1 << 4);    // USART1
	RCC -> AHB1ENR |= (1 << 22);   // DMA2
	RCC -> APB1ENR |= (1 << 21);   // I2C1
	RCC -> AHB1ENR |= (1 << 1);    // GPIOB
}

void systick_init(void) {
    // 1. 設定 SysTick 每 1ms 中斷一次
    // 系統預設 clock = 16MHz
    // 16000000 / 1000 = 16000 counts per ms
    SYSTICK -> LOAD = 16000 - 1;   // reload value
    SYSTICK -> VAL  = 0;            // 清除目前值
    SYSTICK -> CTRL = 0x7;          // bit0=enable, bit1=tickint, bit2=clksource(內部clock)
}

void gpioa_init(void) {
    GPIOA -> MODER &= ~(0x3 << (9*2));
    GPIOA -> MODER |=  (0x2 << (9*2));
    GPIOA -> AFRH &= ~(0xF << ((9-8)*4));
    GPIOA -> AFRH |=  (0x7 << ((9-8)*4));
}

void gpiob_init(void) {
	GPIOB -> MODER &= ~(0x3 << (6*2));
	GPIOB -> MODER |=  (0x2 << (6*2));  // AF mode 10
	GPIOB -> MODER &= ~(0x3 << (7*2));
	GPIOB -> MODER |=  (0x2 << (7*2)); // AF mode 10

	GPIOB -> AFRL  &= ~(0xF << ((6) * 4));
	GPIOB -> AFRL  |=  (0x4 << ((6) * 4));
	GPIOB -> AFRL  &= ~(0xF << ((7) * 4));
	GPIOB -> AFRL  |=  (0x4 << ((7) * 4));

	// ★ I2C 必須的 open-drain + pull-up
	GPIOB -> OTYPER |= (1 << 6);
	GPIOB -> OTYPER |= (1 << 7);
	GPIOB -> PUPDR &= ~(0x3 << (6*2));
	GPIOB -> PUPDR |=  (0x1 << (6*2));
	GPIOB -> PUPDR &= ~(0x3 << (7*2));
	GPIOB -> PUPDR |=  (0x1 << (7*2));
}

void uart_init(void) {
	USART1 -> BRR = 16000000 / 1200;    // baud rate
	USART1 -> CR1 |= (1 << 3);          // TE = 1
	USART1 -> CR1 |= (1 << 13);         // UE = 1
	USART1 -> CR3 = (1 << 7);
}

void i2c_init(void) {
	I2C1 -> CR1 &= ~(1 << 0);

	// 4. 軟體 reset 一下（保險）
	I2C1->CR1 |=  (1 << 15);     // SWRST
	I2C1->CR1 &= ~(1 << 15);

	// 5. 告訴硬體 APB1 是 16MHz
	I2C1->CR2 = 16;              // FREQ[5:0] = 16

	// 6. CCR：standard mode 100kHz
	// CCR = APB1 / (2 × I2C_speed) = 16M / 200k = 80
	I2C1->CCR = 80;

	// 7. TRISE：最大上升時間
	// TRISE = APB1_MHz + 1 = 17（standard mode）
	I2C1->TRISE = 17;

	// 8. 啟用 I2C
	I2C1->CR1 |= (1 << 0);       // PE = 1
}

void i2c_write_reg(uint8_t slave_addr, uint8_t reg_addr, uint8_t data) {
	// 1. START
	I2C1->CR1 |= (1 << 8);                    // START
	while (!(I2C1->SR1 & (1 << 0)));          // 等 SB

	// 2. 送 slave + W
	I2C1->DR = (slave_addr << 1) | 0;         // 寫 DR 同時清 SB
	while (!(I2C1->SR1 & (1 << 1)));          // 等 ADDR

	// 3. 清 ADDR（讀 SR1 + 讀 SR2）
	(void)I2C1->SR1;
	(void)I2C1->SR2;

	// 4. 送 reg_addr
	while (!(I2C1->SR1 & (1 << 7)));          // 等 TXE
	I2C1->DR = reg_addr;

	// 5. 送 data
	while (!(I2C1->SR1 & (1 << 7)));          // 等 TXE
	I2C1->DR = data;

	// 6. 等完整傳完
	while (!(I2C1->SR1 & (1 << 2)));          // 等 BTF

	// 7. STOP
	I2C1->CR1 |= (1 << 9);                    // STOP
}

void i2c_read_regs(uint8_t slave, uint8_t reg, uint8_t *buf, uint8_t len) {
    if (len == 0) return;

    // ============ 前半段：指定 register ============
    I2C1->CR1 |= (1 << 8);                    // START
    while (!(I2C1->SR1 & (1 << 0)));          // 等 SB

    I2C1->DR = (slave << 1) | 0;              // addr + W
    while (!(I2C1->SR1 & (1 << 1)));          // 等 ADDR
    (void)I2C1->SR1; (void)I2C1->SR2;         // 清 ADDR

    while (!(I2C1->SR1 & (1 << 7)));          // 等 TXE
    I2C1->DR = reg;
    while (!(I2C1->SR1 & (1 << 2)));          // 等 BTF（要 RESTART）

    // ============ RESTART → 切讀 ============
    I2C1->CR1 |= (1 << 8);                    // RESTART
    while (!(I2C1->SR1 & (1 << 0)));          // 等 SB

    I2C1->DR = (slave << 1) | 1;              // addr + R

    // ============ 三種 case 分開處理 ============
    if (len == 1) {
        // ---- Case 1：讀單 byte ----
        // 清 ADDR 之前要先 ACK = 0
        I2C1->CR1 &= ~(1 << 10);              // ACK = 0

        while (!(I2C1->SR1 & (1 << 1)));      // 等 ADDR
        (void)I2C1->SR1; (void)I2C1->SR2;     // 清 ADDR

        I2C1->CR1 |= (1 << 9);                // STOP

        while (!(I2C1->SR1 & (1 << 6)));      // 等 RXNE
        buf[0] = I2C1->DR;

    } else if (len == 2) {
        // ---- Case 2：讀 2 byte（特殊，要設 POS）----
        I2C1->CR1 |= (1 << 10);               // ACK = 1
        I2C1->CR1 |= (1 << 11);               // POS = 1

        while (!(I2C1->SR1 & (1 << 1)));      // 等 ADDR
        (void)I2C1->SR1; (void)I2C1->SR2;     // 清 ADDR

        I2C1->CR1 &= ~(1 << 10);              // ACK = 0（給第 2 byte 用）

        while (!(I2C1->SR1 & (1 << 2)));      // 等 BTF（兩 byte 都收完）
        I2C1->CR1 |= (1 << 9);                // STOP

        buf[0] = I2C1->DR;
        buf[1] = I2C1->DR;

        I2C1->CR1 &= ~(1 << 11);              // 清 POS（恢復正常）

    } else {
        // ---- Case 3：讀 N >= 3 byte ----
        I2C1->CR1 |= (1 << 10);               // ACK = 1

        while (!(I2C1->SR1 & (1 << 1)));      // 等 ADDR
        (void)I2C1->SR1; (void)I2C1->SR2;     // 清 ADDR

        // 讀前 N-3 byte（迴圈每次 ACK）
        for (int i = 0; i < len - 3; i++) {
            while (!(I2C1->SR1 & (1 << 6)));  // 等 RXNE
            buf[i] = I2C1->DR;
        }

        // 讀倒數第 3 byte，要等 BTF（不是 RXNE）
        while (!(I2C1->SR1 & (1 << 2)));      // 等 BTF
        I2C1->CR1 &= ~(1 << 10);              // ACK = 0

        buf[len - 3] = I2C1->DR;              // 讀倒數第 3

        while (!(I2C1->SR1 & (1 << 2)));      // 等 BTF
        I2C1->CR1 |= (1 << 9);                // STOP

        buf[len - 2] = I2C1->DR;              // 讀倒數第 2
        buf[len - 1] = I2C1->DR;              // 讀最後一 byte
    }
}

void DMA2_Stream7_IRQHandler(void) {
	if (DMA2 -> HISR & (1 << 27)) {
		DMA2 -> HIFCR |= (1 << 27); // set 1 to clear interrupt register
		dma_done = 1;
	}
}

void uart_dma_send(const void *str, uint16_t len) {
	static uint8_t tx_buf[128];

	while (!dma_done) {};
	dma_done = 0;

	if (len > sizeof(tx_buf)) len = sizeof(tx_buf);
	memcpy(tx_buf, str, len);

	DMA2_Stream7 -> CR &= ~(1 << 0);
	while (DMA2_Stream7 -> CR & ( 1 << 0));

	DMA2 -> HIFCR |= (0x3F << 22); // clear stream7 flag

	DMA2_Stream7 -> NDTR = len;
	DMA2_Stream7 -> PAR = (uint32_t)&(USART1 -> DR);
	DMA2_Stream7 -> M0AR  = (uint32_t)tx_buf;

	DMA2_Stream7 -> CR = (4 << 25)    // Channel 4 (USART1_TX)
                       | (1 << 6)     // DIR = memory → peripheral
                       | (1 << 10)    // MINC = memory 地址遞增
                       | (1 << 4)     // TCIE = Transfer Complete 中斷
                       | (1 << 0);    // EN = 啟動
}

void uart_dma_send_char(char c) {
	uart_dma_send(&c, 1);
}

void uart_dma_send_str(const char *str) {
	uart_dma_send(str, strlen(str));
}

void uart_print_int16(int16_t value) {
    // 處理負數
    if (value < 0) {
        uart_dma_send_char('-');
        value = -value;
    }

    // int16_t 最大 32768，需要 5 位數 + 結尾，buf 開 6
    char buf[6];
    int len = 0;

    if (value == 0) {
        buf[len++] = '0';
    } else {
        int32_t tmp = value;          // 用 int32_t 避免 -32768 取負溢位
        while (tmp > 0) {
            buf[len++] = '0' + (tmp % 10);
            tmp /= 10;
        }
        // 反轉
        for (int i = 0; i < len / 2; i++) {
            char swap = buf[i];
            buf[i] = buf[len - 1 - i];
            buf[len - 1 - i] = swap;
        }
    }

    uart_dma_send(buf, len);
}

int main(void) {
    rcc_init();
    systick_init();
    gpioa_init();
    gpiob_init();
    uart_init();
    i2c_init();

    NVIC->ISER[2] |= (1 << 6);

    uart_dma_send_str("Boot\r\n");

    // Step 3：先確認 WHO_AM_I
    uint8_t id;
    i2c_read_regs(0x68, 0x75, &id, 1);

    uart_dma_send_str("WHO_AM_I = 0x");
    char hex[3];
    const char *table = "0123456789ABCDEF";
    hex[0] = table[(id >> 4) & 0xF];
    hex[1] = table[id & 0xF];
    hex[2] = '\0';
    uart_dma_send_str(hex);
    uart_dma_send_str("\r\n");

    if (id != 0x68) {
        uart_dma_send_str("MPU not found\r\n");
        while (1);
    }

    // Step 4：叫醒 MPU
    i2c_write_reg(0x68, 0x6B, 0x00);
    uart_dma_send_str("Wake up\r\n");

    // Step 5：連讀加速度
    uint8_t buf[6];
    while (1) {
        i2c_read_regs(0x68, 0x3B, buf, 6);

        int16_t ax = (buf[0] << 8) | buf[1];
        int16_t ay = (buf[2] << 8) | buf[3];
        int16_t az = (buf[4] << 8) | buf[5];

        // 印出來（int16 print 你之後加，先送固定字串確認讀取沒卡）
        uart_dma_send_str("AX=");
        uart_print_int16(ax);
        uart_dma_send_str(" AY=");
        uart_print_int16(ay);
        uart_dma_send_str(" AZ=");
        uart_print_int16(az);
        uart_dma_send_str("\r\n");

        delay_ms(1000);
    }
}
